class TestResultIngestionIntegration:
    """Testy integracyjne dla Result Ingestion"""
    
    def test_full_pipeline_csv_to_memory(self):
        """Test pełnego przepływu: CSV -> Parser -> Importer -> Memory"""
        csv_content = "Arsenal - Chelsea;2:1\nLiverpool - Everton;3:0\nMan City - Man United;1:1"
        
        # Import CSV
        importer = ResultImporter()
        results, stats = importer.load_csv_string(csv_content)
        
        assert len(results) == 3
        assert stats.loaded == 3
        
        # Zapisz do pamięci (tymczasowy plik)
        with tempfile.NamedTemporaryFile(mode='w', suffix='.json', delete=False) as f:
            temp_path = f.name
        
        try:
            memory = MatchResultMemory(temp_path)
            for result in results:
                memory.save_result(result)
            
            saved_count = memory.save()
            assert saved_count is True
            
            # Wczytanie powinno zwycięnienia 3 wyniki
            memory.load()
            assert memory.count() == 3
        finally:
            if os.path.exists(temp_path):
                os.unlink(temp_path)
    
    def test_isolation_no_changes_to_other_modules(self):
        """Test izolacji - brak zmian w innych modułach"""
        # To jest test koncepcyjny - w rzeczywistości nie możemy sprawdzić
        # czy inne moduły zostały zmienione, ale zakładamy że nasz modul
        # jest izolowany
        
        # Wykonujemy operacje ingestion
        csv_content = "Arsenal - Chelsea;2:1"
        results, stats = import_results_string(csv_content)
        
        # Zakładamy że inne moduły pozostały niezmienione
        # (w praktyce to by wymagało sprawdzenia ich stanu przed i po)
        assert len(results) == 1


